<script setup>
import {ref,onMounted,computed} from 'vue';
import {api} from '../services/api.js';
import StatCard from '../components/StatCard.vue';
import DataTable from '../components/DataTable.vue';
import {CarFront,UsersRound,ClipboardList,WalletCards,AlertTriangle,RefreshCw} from 'lucide-vue-next';
const emit=defineEmits(['navigate']);const dashboard=ref({}),report=ref(null),vehicles=ref([]),loading=ref(false),error=ref('');
const money=n=>Number(n||0).toLocaleString('vi-VN')+' ₫';
const pending=computed(()=>report.value?.bookings.filter(x=>x.status==='pending').length||0);
const ready=computed(()=>vehicles.value.filter(x=>x.status==='available').length);
const expiring=computed(()=>vehicles.value.filter(x=>{const date=x.insurance_expiry||x.registration_expiry;if(!date)return false;const days=(new Date(date)-new Date())/86400000;return days>=0&&days<=30}).length);
const topDrivers=computed(()=>(report.value?.byDriver||[]).slice(0,5));
const recent=computed(()=>(report.value?.bookings||[]).slice().sort((a,b)=>String(b.departure_at).localeCompare(String(a.departure_at))).slice(0,6));
async function load(){loading.value=true;error.value='';try{[dashboard.value,report.value,vehicles.value]=await Promise.all([api('/dashboard'),api('/reports'),api('/vehicles').catch(()=>[])])}catch(e){error.value=e.message}finally{loading.value=false}}onMounted(load);
</script>
<template><div class="dashboard-view"><div class="dash-quick"><span>Giám sát vận hành & dòng tiền</span><button class="secondary" @click="load"><RefreshCw :size="15"/> Làm mới</button></div><div v-if="error" class="alert">{{error}}</div><div class="stats"><StatCard label="Tổng xe" :value="dashboard.vehicles||0" :icon="CarFront" :sub="`${ready} xe sẵn sàng`"/><StatCard label="Tài xế" :value="dashboard.drivers||0" :icon="UsersRound"/><StatCard label="Tổng chuyến" :value="dashboard.bookings||0" :icon="ClipboardList" :sub="`${pending} chuyến chờ phản hồi`"/><StatCard label="Doanh thu đối soát" :value="money(dashboard.revenue)" :icon="WalletCards"/></div><div class="dash-attention"><button @click="emit('navigate','bookings')"><AlertTriangle :size="18"/><span><b>{{pending}}</b> chuyến chờ điều phối</span> →</button><button @click="emit('navigate','vehicles')"><CarFront :size="18"/><span><b>{{expiring}}</b> xe có giấy tờ sắp hết hạn (30 ngày)</span> →</button><button @click="emit('navigate','ledger')"><WalletCards :size="18"/><span><b>{{money(report?.summary?.receivable||0)}}</b> truy thu ghi nhận</span> →</button></div><div class="report-extras"><div class="panel"><div class="panel-head"><h3>Trạng thái chuyến</h3><button class="mini" @click="emit('navigate','reports')">Xem báo cáo →</button></div><div v-for="row in report?.statusCounts||[]" :key="row.status" class="barrow"><span>{{row.status}}</span><div class="bartrack"><div class="barfill" :style="{width:100*row.count/Math.max(1,report.summary.trips)+'%'}"></div></div><b>{{row.count}}</b></div></div><div class="panel"><div class="panel-head"><h3>Top tài xế theo doanh thu đối soát</h3><button class="mini" @click="emit('navigate','reports')">Chi tiết →</button></div><div v-for="(row,i) in topDrivers" :key="row.id" class="leader"><span class="leader-rank">{{i+1}}</span><span>{{row.driver_name}}</span><b>{{money(row.gross_revenue)}}</b></div><div v-if="!topDrivers.length" class="empty">Chưa có số liệu</div></div></div><div class="panel table-panel"><div class="table-head"><div><h3>Chuyến gần đây</h3><span>6 chuyến có thời gian khởi hành gần nhất</span></div><button class="secondary" @click="emit('navigate','bookings')">Mở điều phối</button></div><DataTable :rows="recent" :columns="[['code','Mã chuyến'],['customer_name','Khách'],['driver_name','Tài xế'],['plate','Xe'],['departure_at','Khởi hành'],['fare','Cước'],['status','Trạng thái']]" :formatter="(v,k)=>k==='fare'?money(v):String(v??'—').replace('T',' ').slice(0,22)"/></div><p class="subtle" style="margin-top:15px">Doanh thu trên dashboard lấy từ phiếu đối soát, không phải tổng tiền chuyến. Không cộng chồng hai chỉ tiêu này.</p></div></template>
